import {
  ArgumentsHost,
  Catch,
  ExceptionFilter,
  HttpException,
  HttpStatus,
} from '@nestjs/common';

@Catch()
export class HttpExceptionFilter implements ExceptionFilter {
  catch(exception: any, host: ArgumentsHost) {
    const ctx = host.switchToHttp();

    const response = ctx.getResponse();

    const request = ctx.getRequest();

    const status =
      exception instanceof HttpException
        ? exception.getStatus()
        : HttpStatus.INTERNAL_SERVER_ERROR;

    response.status(status).json({
      success: false,
      statusCode: status,
      path: request.url,
      message:
        exception?.response?.message ||
        exception.message ||
        'Internal server error',
      timestamp: new Date().toISOString(),
    });
  }
}

import {
  ArgumentsHost,
  Catch,
  ExceptionFilter,
  HttpException,
  HttpStatus,
} from '@nestjs/common';

@Catch()
export class HttpExceptionFilter implements ExceptionFilter {
  catch(exception: any, host: ArgumentsHost) {
    const ctx = host.switchToHttp();
    const response = ctx.getResponse();
    const request = ctx.getRequest();

    const status =
      exception instanceof HttpException
        ? exception.getStatus()
        : HttpStatus.INTERNAL_SERVER_ERROR;

    const message =
      exception?.response?.message ??
      exception?.message ??
      'Internal server error';

    response.status(status).json({
      success: false,
      message,
      data: {},
      statusCode: status,
      path: request.url,
      timestamp: new Date().toISOString(),
    });
  }
}

import {
  CallHandler,
  ExecutionContext,
  Injectable,
  NestInterceptor,
} from '@nestjs/common';
import { map, Observable } from 'rxjs';

@Injectable()
export class ResponseInterceptor implements NestInterceptor {
  intercept(_context: ExecutionContext, next: CallHandler): Observable<any> {
    return next.handle().pipe(
      map((data) => ({
        success: true,
        message: 'OK',
        data,
      })),
    );
  }
}

import { createParamDecorator, ExecutionContext } from '@nestjs/common';
import { requestContext } from './request-context';

export const CurrentRequestContext = createParamDecorator(
  (_data: unknown, _ctx: ExecutionContext) => {
    return requestContext.get();
  },
);

import { Injectable, NestMiddleware } from '@nestjs/common';
import { randomUUID } from 'node:crypto';
import { requestContext } from './request-context';

@Injectable()
export class RequestContextMiddleware implements NestMiddleware {
  use(req: any, res: any, next: () => void) {
    const incomingRequestId =
      req.headers['x-request-id']?.toString() ?? randomUUID();

    const incomingCorrelationId =
      req.headers['x-correlation-id']?.toString() ?? incomingRequestId;

    requestContext.run(
      {
        requestId: incomingRequestId,
        correlationId: incomingCorrelationId,
      },
      () => {
        res.setHeader('x-request-id', incomingRequestId);
        res.setHeader('x-correlation-id', incomingCorrelationId);
        next();
      },
    );
  }
}

import { Injectable } from '@nestjs/common';
import { PrismaService } from '../database/prisma.service';

export interface IAuditableEntity {
  id: string;
  tenantId: string;
  createdById?: string | null;
  createdAt: Date;
  updatedById?: string | null;
  updatedAt: Date;
  deletedById?: string | null;
  deletedAt?: Date | null;
}

/**
 * Base service providing common functionality for all modules:
 * - Soft delete support
 * - Audit trail (createdBy, updatedBy, deletedBy)
 * - Multi-tenant isolation
 * - Pagination helpers
 */
@Injectable()
export class BaseService {
  constructor(protected prisma: PrismaService) {}

  /**
   * Apply tenant filter to any where clause
   */
  protected withTenantFilter<T extends { tenantId?: string }>(
    where: T,
    tenantId: string,
  ): T {
    return {
      ...where,
      tenantId,
    };
  }

  /**
   * Apply soft delete filter (exclude deleted records by default)
   */
  protected withoutDeleted<T extends { deletedAt?: any }>(
    where: T,
    includeDeleted: boolean = false,
  ): T {
    if (includeDeleted) {
      return where;
    }
    return {
      ...where,
      deletedAt: null,
    };
  }

  /**
   * Standardized pagination parameters
   */
  protected getPaginationParams(skip?: number, take?: number) {
    const DEFAULT_SKIP = 0;
    const DEFAULT_TAKE = 10;
    const MAX_TAKE = 100;

    return {
      skip: Math.max(0, skip ?? DEFAULT_SKIP),
      take: Math.min(take ?? DEFAULT_TAKE, MAX_TAKE),
    };
  }

  /**
   * Format paginated response
   */
  protected formatPaginatedResponse<T>(
    data: T[],
    total: number,
    skip: number,
    take: number,
  ) {
    return {
      data,
      pagination: {
        total,
        skip,
        take,
        pages: Math.ceil(total / take),
      },
    };
  }

  /**
   * Soft delete - mark record as deleted
   */
  protected async softDelete(
    model: { update: (args: any) => Promise<unknown> },
    where: any,
    userId: string,
  ) {
    return await model.update({
      where,
      data: {
        deletedAt: new Date(),
        deletedById: userId,
      },
    });
  }

  /**
   * Soft restore - unmark deleted record
   */
  protected async softRestore(
    model: { update: (args: any) => Promise<unknown> },
    where: any,
  ) {
    return await model.update({
      where,
      data: {
        deletedAt: null,
        deletedById: null,
      },
    });
  }

  /**
   * Add audit fields to create data
   */
  protected addAuditFields(data: any, userId: string) {
    return {
      ...data,
      createdById: userId,
      updatedById: userId,
    };
  }

  /**
   * Add audit fields to update data
   */
  protected addUpdateAuditFields(data: any, userId: string) {
    return {
      ...data,
      updatedById: userId,
      updatedAt: new Date(),
    };
  }
}

